def can_transform(k: int, s: str, t: str) -> bool:
    """ Determine if string s can be transformed into string t using at most k operations.

    Available operations:
    - Insert any character at any position in the string
    - Delete any character from the string
    - Replace any character with another character

    Args:
        k: Maximum number of operations allowed (1 <= k <= 20)
        s: Source string (1 <= len(s) <= 500000)
        t: Target string (1 <= len(t) <= 500000)

    Returns:
        True if s can be transformed into t with at most k operations, False otherwise

    >>> can_transform(3, 'abc', 'awtf')
    True
    >>> can_transform(2, 'abc', 'awtf')
    False
    >>> can_transform(17, 'twothousandtwentyfour', 'happynewyear')
    True
    """
    if k < 0:
        return False
    if abs(len(s) - len(t)) > k:
        return False

    # Equal ends can be removed without changing edit distance.
    start = 0
    n, m = len(s), len(t)
    while start < n and start < m and s[start] == t[start]:
        start += 1
    while n > start and m > start and s[n - 1] == t[m - 1]:
        n -= 1
        m -= 1
    s, t = s[start:n], t[start:m]
    n, m = len(s), len(t)
    if not n or not m:
        return max(n, m) <= k
    if max(n, m) <= k:
        return True

    # For each diagonal x-y, retain the furthest source position reachable
    # with the current edit budget, then consume matching characters freely.
    frontier = {0: 0}
    for edits in range(1, k + 1):
        following = {}
        for diagonal, x in frontier.items():
            y = x - diagonal
            if x < n:
                new_diagonal = diagonal + 1  # Delete s[x].
                following[new_diagonal] = max(
                    following.get(new_diagonal, -1), x + 1
                )
            if y < m:
                new_diagonal = diagonal - 1  # Insert t[y].
                following[new_diagonal] = max(
                    following.get(new_diagonal, -1), x
                )
            if x < n and y < m:
                following[diagonal] = max(
                    following.get(diagonal, -1), x + 1
                )

        frontier = {}
        for diagonal, x in following.items():
            y = x - diagonal
            while x < n and y < m and s[x] == t[y]:
                x += 1
                y += 1
            if x == n and y == m:
                return True
            # Even with perfect matches, this many further edits are needed.
            if abs((n - x) - (m - y)) <= k - edits:
                frontier[diagonal] = x
        if not frontier:
            return False
    return False

from functools import lru_cache
from math import gcd


# Contains every possible prime power in a zero-free digit sum below 82.
_PRODUCT_MODULUS = 64 * 81 * 25 * 49


@lru_cache(None)
def _next_product(product: int, digit: int) -> int:
    return gcd(product * digit, _PRODUCT_MODULUS)


@lru_cache(None)
def _bad_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count zero-free completions whose digit sum does not divide the product."""
    if remaining == 0:
        return int(product % digit_sum != 0)
    return sum(
        _bad_suffix(remaining - 1, digit_sum + digit,
                    _next_product(product, digit))
        for digit in range(1, 10)
    )


def _beautiful_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(char) for char in str(bound)]
    bad = sum(_bad_suffix(length, 0, 1)
              for length in range(1, len(digits)))
    digit_sum = 0
    product = 1
    for index, limit in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(1, limit):
            bad += _bad_suffix(remaining, digit_sum + digit,
                               _next_product(product, digit))
        if limit == 0:
            break
        digit_sum += limit
        product = _next_product(product, limit)
    else:
        bad += int(product % digit_sum != 0)
    # Every positive number containing a zero is automatically beautiful.
    return bound - bad


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive interval [l, r].

    A number is beautiful if its digit product is divisible by its digit sum.
    The bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _beautiful_up_to(r) - _beautiful_up_to(l - 1)

def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Count replacements having at least k reducible contiguous substrings.

    A nonempty string is reducible precisely when its A, B, and C counts
    have the same parity. Return the number of replacements modulo 998244353.

    Args:
        n: Length of s, between 1 and 50.
        k: Required number of good substrings.
        s: A string over A, B, C, and '?'.

    >>> count_good_string_replacements(4, 2, 'A?AB')
    1
    >>> count_good_string_replacements(1, 0, 'A')
    1
    >>> count_good_string_replacements(2, 1, 'CC')
    1
    """
    mod = 998244353
    if k == 0:
        return pow(3, s.count('?'), mod)

    # Map A, B, C to the three nonzero elements of the XOR group.
    # A good substring has equal prefix XORs at its endpoints.
    # Adjacent prefixes differ, so the greatest possible collision count
    # comes from alternating between two states.
    if k > n * n // 4:
        return 0

    labels = {'A': (1,), 'B': (2,), 'C': (3,), '?': (1, 2, 3)}
    # Store counts of prefix states 0, 1, 2 and the current XOR state.
    # The count of state 3 is implied by the number of prefixes processed.
    dp = {(1, 0, 0, 0): 1}
    for ch in s:
        following = {}
        choices = labels[ch]
        for (a, b, c, current), ways in dp.items():
            for label in choices:
                target = current ^ label
                if target == 0:
                    state = (a + 1, b, c, target)
                elif target == 1:
                    state = (a, b + 1, c, target)
                elif target == 2:
                    state = (a, b, c + 1, target)
                else:
                    state = (a, b, c, target)
                following[state] = (following.get(state, 0) + ways) % mod
        dp = following

    total = 0
    prefix_count = len(s) + 1
    for (a, b, c, current), ways in dp.items():
        d = prefix_count - a - b - c
        good = (a * (a - 1) + b * (b - 1) +
                c * (c - 1) + d * (d - 1)) // 2
        if good >= k:
            total += ways
    return total % mod

