def sum_good_sequence_scores(n: int, a: list[int]) -> int:
    """Sum the products of all positive good sequences, modulo 998244353.

    Adjacent reduced ratios have numerator times denominator a[i], and
    the gcd of the entire sequence is one.  Constraints: 2 <= n <= 1000,
    len(a) == n - 1, and 1 <= a[i] <= 1000.
    """
    mod = 998244353

    # For each prime, adjacent exponents differ by exactly its exponent
    # in a[i].  Choices for different primes are independent.
    factors = {}
    for i, value in enumerate(a):
        p = 2
        while p * p <= value:
            if value % p == 0:
                exponent = 0
                while value % p == 0:
                    value //= p
                    exponent += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = exponent
            p += 1
        if value > 1:
            if value not in factors:
                factors[value] = [0] * (n - 1)
            factors[value][i] = 1

    answer = 1
    for prime, steps in factors.items():
        limit = max(sum(steps), n * max(steps))
        powers = [1] * (limit + 1)
        for h in range(1, limit + 1):
            powers[h] = powers[h - 1] * prime % mod

        # dp[h] sums prime**(sum of exponents) for prefixes whose
        # minimum exponent is zero and whose last exponent is h.
        dp = [1]
        for length, step in enumerate(steps, 1):
            if step == 0:
                dp = [weight * powers[h] % mod
                      for h, weight in enumerate(dp)]
                continue

            nxt = [0] * (len(dp) + step)
            for h, weight in enumerate(dp):
                if not weight:
                    continue
                higher = h + step
                nxt[higher] = (nxt[higher] + weight * powers[higher]) % mod
                if h >= step:
                    lower = h - step
                    nxt[lower] = (nxt[lower] + weight * powers[lower]) % mod
                else:
                    # A new minimum shifts all previous exponents up;
                    # the newly appended exponent becomes zero.
                    shift = step - h
                    nxt[0] = (nxt[0] + weight * powers[length * shift]) % mod
            dp = nxt
        answer = answer * (sum(dp) % mod) % mod

    return answer

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether the Levenshtein distance between s and t is at most k.

    An operation inserts, deletes, or replaces one character. The supported
    bounds are 1 <= k <= 20 and string lengths up to 500000.
    """
    if abs(len(s) - len(t)) > k:
        return False
    if s == t:
        return True

    # Equal ends do not affect edit distance.
    start = 0
    limit = min(len(s), len(t))
    while start < limit and s[start] == t[start]:
        start += 1
    end_s, end_t = len(s), len(t)
    while end_s > start and end_t > start and s[end_s - 1] == t[end_t - 1]:
        end_s -= 1
        end_t -= 1
    s, t = s[start:end_s], t[start:end_t]
    n, m = len(s), len(t)
    if max(n, m) <= k:
        return True
    if not n or not m:
        return False

    # For each diagonal d = i - j, retain the furthest source position
    # reachable with the current number of edits, followed by free matches.
    frontier = {0: 0}
    for _ in range(k):
        following = {}
        for diagonal, i in frontier.items():
            j = i - diagonal
            if i < n and j < m:
                following[diagonal] = max(following.get(diagonal, -1), i + 1)
            if i < n:
                d = diagonal + 1
                following[d] = max(following.get(d, -1), i + 1)
            if j < m:
                d = diagonal - 1
                following[d] = max(following.get(d, -1), i)

        for diagonal, i in following.items():
            j = i - diagonal
            while i < n and j < m and s[i] == t[j]:
                i += 1
                j += 1
            if i == n and j == m:
                return True
            following[diagonal] = i
        frontier = following
    return False

