def kth_smallest_amount(coins: List[int], k: int) -> int:
    """ Given an array of coin denominations and an integer k, return the k-th smallest amount
    that can be made using these coins. You have infinite coins of each denomination, but
    cannot combine coins of different denominations in a single amount.

    Each coin denomination produces its multiples (e.g., coin 3 produces 3, 6, 9, 12, ...).
    The k-th smallest among all possible amounts from all denominations is returned.

    Args:
        coins: List of distinct positive integers representing coin denominations (1-15 elements, each 1-25)
        k: The position of the desired amount (1-based indexing, 1 <= k <= 2*10^9)

    Returns:
        The k-th smallest amount that can be made

    >>> kth_smallest_amount([3, 6, 9], 3)
    9
    >>> kth_smallest_amount([5, 2], 7)
    12
    """
    # A denomination divisible by a smaller one adds no new amounts.
    denominations = []
    for coin in sorted(set(coins)):
        if not any(coin % smaller == 0 for smaller in denominations):
            denominations.append(coin)

    low, high = 1, denominations[0] * k
    # Aggregate inclusion-exclusion terms that have the same LCM.
    coefficients = {}
    for coin in denominations:
        additions = {coin: 1}
        for divisor, coefficient in coefficients.items():
            common = divisor // gcd(divisor, coin) * coin
            if common <= high:
                additions[common] = additions.get(common, 0) - coefficient
        for divisor, coefficient in additions.items():
            coefficients[divisor] = coefficients.get(divisor, 0) + coefficient
            if coefficients[divisor] == 0:
                del coefficients[divisor]

    while low < high:
        middle = (low + high) // 2
        count = sum(coefficient * (middle // divisor)
                    for divisor, coefficient in coefficients.items())
        if count >= k:
            high = middle
        else:
            low = middle + 1
    return low

from math import isqrt


def _make_signatures():
    tables = [[0]]
    for width in range(1, 5):
        previous = tables[-1]
        tables.append([
            previous[value // 10] + (1 << (4 * (value % 10)))
            for value in range(10 ** width)
        ])
    return tables


_SIGNATURES = _make_signatures()


def count_square_permutations(n: int, s: str) -> int:
    """Count distinct squares whose n-digit, zero-padded form permutes s.

    Leading zeros are permitted. For example, '010' forms the squares 1
    and 100, while '4320' forms 324 and 2304.
    """
    target = sum(1 << (4 * int(digit)) for digit in s)
    digit_sum = sum(map(int, s)) % 9
    residues = [r for r in range(9) if r * r % 9 == digit_sum]
    if not residues:
        return 0

    limit = isqrt(int("".join(sorted(s, reverse=True))))
    # A four-bit field per digit holds every frequency, since n <= 13.
    # Fixed-width chunk signatures include all necessary leading zeros.
    blocks = _SIGNATURES[4]
    top = _SIGNATURES[(n - 1) % 4 + 1]
    answer = 0
    if n <= 4:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                if top[root * root] == target:
                    answer += 1
    elif n <= 8:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                if blocks[square % 10000] + top[square // 10000] == target:
                    answer += 1
    elif n <= 12:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                low = blocks[square % 10000]
                square //= 10000
                if low + blocks[square % 10000] + top[square // 10000] == target:
                    answer += 1
    else:
        for residue in residues:
            for root in range(residue, limit + 1, 9):
                square = root * root
                low = blocks[square % 10000]
                square //= 10000
                low += blocks[square % 10000]
                square //= 10000
                if low + blocks[square % 10000] + top[square // 10000] == target:
                    answer += 1
    return answer

