def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Return the fewest adjacent-stone-pair moves from s to t.

    The two empty cells initially follow the n stones and must also follow
    the stones in the target. A move preserves the order of the moved pair.
    Return -1 when no sequence of legal moves reaches the target.
    """
    if s == t:
        return 0
    if s.count('W') != t.count('W'):
        return -1

    # A state contains the white-stone bitmask and the index of the first
    # empty cell. Black stones occupy every remaining nonempty cell.
    start_mask = sum(1 << i for i, c in enumerate(s) if c == 'W')
    target_mask = sum(1 << i for i, c in enumerate(t) if c == 'W')
    start = (start_mask << 4) | n
    target = (target_mask << 4) | n

    # A source pair cannot overlap either empty cell.
    sources = [tuple(i for i in range(n + 1)
                     if i + 1 < gap or i > gap + 1)
               for gap in range(n + 1)]
    front = {start}
    back = {target}
    forward_dist = {start: 0}
    backward_dist = {target: 0}

    # Every move is reversible, so either end can supply the next BFS layer.
    while front and back:
        if len(front) > len(back):
            front, back = back, front
            forward_dist, backward_dist = backward_dist, forward_dist
        next_front = set()
        for state in front:
            mask, gap = state >> 4, state & 15
            distance = forward_dist[state] + 1
            for source in sources[gap]:
                pair = (mask >> source) & 3
                moved_mask = (mask ^ (pair << source)) | (pair << gap)
                neighbor = (moved_mask << 4) | source
                if neighbor in forward_dist:
                    continue
                if neighbor in backward_dist:
                    return distance + backward_dist[neighbor]
                forward_dist[neighbor] = distance
                next_front.add(neighbor)
        front = next_front
    return -1

from functools import lru_cache
from math import gcd


# Contains every possible prime power in a zero-free digit sum below 82.
_PRODUCT_MODULUS = 64 * 81 * 25 * 49


@lru_cache(None)
def _next_product(product: int, digit: int) -> int:
    return gcd(product * digit, _PRODUCT_MODULUS)


@lru_cache(None)
def _bad_suffix(remaining: int, digit_sum: int, product: int) -> int:
    """Count zero-free completions whose digit sum does not divide the product."""
    if remaining == 0:
        return int(product % digit_sum != 0)
    return sum(
        _bad_suffix(remaining - 1, digit_sum + digit,
                    _next_product(product, digit))
        for digit in range(1, 10)
    )


def _beautiful_up_to(bound: int) -> int:
    if bound <= 0:
        return 0
    digits = [int(char) for char in str(bound)]
    bad = sum(_bad_suffix(length, 0, 1)
              for length in range(1, len(digits)))
    digit_sum = 0
    product = 1
    for index, limit in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(1, limit):
            bad += _bad_suffix(remaining, digit_sum + digit,
                               _next_product(product, digit))
        if limit == 0:
            break
        digit_sum += limit
        product = _next_product(product, limit)
    else:
        bad += int(product % digit_sum != 0)
    # Every positive number containing a zero is automatically beautiful.
    return bound - bad


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive interval [l, r].

    A number is beautiful if its digit product is divisible by its digit sum.
    The bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _beautiful_up_to(r) - _beautiful_up_to(l - 1)

